export function documentKindLabel(kind: OslDocumentKind): string { return ({ note: "Note", document: "Document", spreadsheet: "Spreadsheet", drawing: "Drawing", presentation: "Presentation", photo: "Photo", video: "Video", audio: "Audio", model3d: "3D project" })[kind]; }
export function searchableDocumentText(note: OslNote): string {
  if (note.kind === "document") { const project = parseOslCreativeProject(note.body); if (project) return `${project.name} ${project.mime} ${project.editor} encrypted creative asset`; const document = parseDocument(note.body); if (document) return documentPlainText(document); }
  if (note.kind === "spreadsheet") return Object.values(parseSheet(note.body)?.cells ?? {}).join(" ");
  if (note.kind === "drawing") return (parseDrawing(note.body)?.items ?? []).map((item) => item.text).join(" ");
  if (note.kind === "presentation") return (parsePresentation(note.body)?.slides ?? []).flatMap((slide) => [slide.title, slide.body]).join(" ");
  return note.body;
}

function commonHeader(note: OslNote, saveState: NotesSaveState, canUndo = false, canRedo = false): string {
  const save = saveState === "saving" ? "Encrypting…" : saveState === "error" ? "Save failed" : "Saved locally";
  return `<header><div class="office-file-kind"><span>${documentKindLabel(note.kind)}</span><input id="note-title" value="${escapeHtml(note.title)}" maxlength="120" aria-label="File title" placeholder="Untitled ${documentKindLabel(note.kind).toLowerCase()}"></div><div><span class="notes-save-state ${saveState}" role="status">${save}</span><button class="notes-icon-button" data-note-undo aria-label="Undo" ${canUndo ? "" : "disabled"}>↶</button><button class="notes-icon-button" data-note-redo aria-label="Redo" ${canRedo ? "" : "disabled"}>↷</button><button class="notes-icon-button" data-note-export aria-label="Export portable copy">⇩</button><button class="notes-icon-button" data-note-original aria-label="Export linked original file">⤓</button><button class="notes-icon-button" data-note-history aria-label="Version history">◷</button><button class="notes-icon-button ${note.pinned ? "active" : ""}" data-note-pin aria-label="${note.pinned ? "Unpin" : "Pin"}">⌖</button><button class="notes-icon-button ${note.favorite ? "active" : ""}" data-note-favorite aria-label="Favorite">☆</button><button class="notes-icon-button" data-note-trash aria-label="Move to Trash">×</button></div></header>`;
}
function commonFooter(note: OslNote): string { return `<footer><label><span>Folder</span><input id="note-folder" value="${escapeHtml(note.folder)}" maxlength="80" placeholder="Workspace"></label><label><span>Tags</span><input id="note-tags" value="${escapeHtml(note.tags.join(", "))}" maxlength="540" placeholder="project, shared"></label><span>Encrypted</span></footer>`; }
function officeAttachments(attachments: OslAssetDescriptor[]): string {
  const size = (bytes: number) => bytes < 1024 ? `${bytes} B` : bytes < 1024 * 1024 ? `${(bytes / 1024).toFixed(1)} KiB` : `${(bytes / 1024 / 1024).toFixed(1)} MiB`;
  const rows = attachments.map((asset) => `<article><span><strong>${escapeHtml(asset.name)}</strong><small>${escapeHtml(asset.mime)} · ${size(asset.size)}</small></span><div><button data-note-attachment-export="${asset.id}" title="Preserves the exact original file, including its metadata">Export exact original</button><button data-note-attachment-remove="${asset.id}" aria-label="Remove ${escapeHtml(asset.name)} from this file">Remove</button></div></article>`).join("");
  return `<details class="notes-attachments office-attachments" ${attachments.length ? "" : "open"}><summary><span><strong>Encrypted attachments</strong><small>${attachments.length} local file${attachments.length === 1 ? "" : "s"}</small></span></summary><header><span><small>Available to this file only</small></span><button data-note-attach type="button">＋ Attach files</button><input data-note-attachment-input type="file" multiple hidden></header><div>${rows || '<p class="notes-attachments-empty">Attach images or PDFs here before placing them on an infinite canvas.</p>'}</div>${attachments.length ? '<footer>Normal exports omit source metadata. “Export exact original” preserves the selected file byte-for-byte, including metadata.</footer>' : ""}</details>`;
}

function documentEditor(note: OslNote, mode: NotesEditorMode): string {
  const plugin = parseOslPluginProject(note.body); if (plugin) return `<div class="creative-asset-editor osl-plugin-editor" data-osl-plugin="${plugin.assetId}"><div class="creative-asset-toolbar"><span><strong>${escapeHtml(plugin.manifest.name)}</strong><small>${escapeHtml(plugin.manifest.id)} · ${escapeHtml(plugin.manifest.version)} · encrypted .oslmod</small></span><span class="notes-save-state saved">No ambient access</span></div><div class="creative-asset-workspace"><section class="creative-asset-preview"><div><h2>Sandboxed command</h2><p>${escapeHtml(plugin.manifest.description)}</p><label>Integer input<input type="number" value="0" step="1" data-plugin-input></label><button class="button primary" data-plugin-run>Run command</button><output data-plugin-result aria-live="polite">Ready</output></div></section><aside><h2>Execution boundary</h2><p>WebAssembly interpreter · 32 MiB memory · 2,000,000 fuel · no WASI · no host imports · user-invoked only.</p><p>Declared permission: <code>ui:command</code></p></aside></div></div>`;
  const project = parseOslCreativeProject(note.body); if (project) return creativeAssetEditor(project);
  const document = parseDocument(note.body); if (!document) return '<div class="creative-asset-loading error">This document is malformed.</div>';
  const commentCount = (blockId: string) => document.review.comments.filter((comment) => comment.blockId === blockId && !comment.resolved).length;
  const blockMarkup = document.blocks.map((block) => block.type === "pagebreak" ? `<div class="office-page-break" data-document-block="${block.id}"><span>Page break</span><button data-document-delete="${block.id}" aria-label="Remove page break">×</button></div>` : `<section class="office-document-block type-${block.type} ${commentCount(block.id) ? "has-comment" : ""}" data-document-block="${block.id}">${block.type === "checklist" ? `<input type="checkbox" data-document-checked="${block.id}" ${block.checked ? "checked" : ""} aria-label="Complete item">` : ""}<textarea data-document-text="${block.id}" data-document-type="${block.type}" data-document-align="${block.align}" maxlength="10000" spellcheck="true" aria-label="${block.type}">${escapeHtml(block.text)}</textarea>${commentCount(block.id) ? `<span class="document-comment-count" aria-label="${commentCount(block.id)} unresolved comments">${commentCount(block.id)}</span>` : ""}<button data-document-delete="${block.id}" aria-label="Delete block" ${document.blocks.length === 1 ? "disabled" : ""}>×</button></section>`).join("");
  const rich = (text: string) => escapeHtml(text).replace(/`([^`\n]+)`/gu, "<code>$1</code>").replace(/\*\*([^*\n]+)\*\*/gu, "<strong>$1</strong>").replace(/_([^_\n]+)_/gu, "<em>$1</em>").replace(/==([^=\n]+)==/gu, "<mark>$1</mark>"); const table = (text: string) => `<table>${text.split(/\r?\n/u).slice(0, 100).map((row) => `<tr>${row.split("\t").slice(0, 20).map((cell) => `<td>${rich(cell)}</td>`).join("")}</tr>`).join("")}</table>`;
  const preview = document.blocks.map((block) => block.type === "pagebreak" ? '<hr class="office-page-break-preview">' : block.type === "table" ? table(block.text) : block.type === "heading1" ? `<h1>${rich(block.text)}</h1>` : block.type === "heading2" ? `<h2>${rich(block.text)}</h2>` : block.type === "quote" ? `<blockquote>${rich(block.text)}</blockquote>` : `<p style="text-align:${block.align}">${block.type === "checklist" ? `${block.checked ? "☑" : "☐"} ` : ""}${rich(block.text).replace(/\n/gu, "<br>")}</p>`).join("");
  const comments = document.review.comments.map((comment) => `<article class="document-review-item ${comment.resolved ? "resolved" : ""}"><small>${comment.resolved ? "Resolved" : "Comment"} · ${new Date(comment.createdAt).toLocaleString()}</small><p>${escapeHtml(comment.body)}</p>${comment.quote ? `<blockquote>${escapeHtml(comment.quote)}</blockquote>` : ""}<div><button data-document-comment-resolve="${comment.id}">${comment.resolved ? "Reopen" : "Resolve"}</button><button data-document-comment-delete="${comment.id}">Delete</button></div></article>`).join("");
  const changes = document.review.changes.map((change) => `<article class="document-review-item change"><small>Tracked edit · ${new Date(change.createdAt).toLocaleString()}</small><p><del>${escapeHtml(change.before.slice(0, 240) || "Empty")}</del><ins>${escapeHtml(change.after.slice(0, 240) || "Empty")}</ins></p><div><button data-document-change-accept="${change.id}">Accept</button><button data-document-change-reject="${change.id}">Reject</button></div></article>`).join("");
  const review = `<section class="office-document-review" aria-label="Document review"><h2>Review</h2><label class="creative-check"><span>Track text changes</span><input type="checkbox" data-document-track ${document.review.trackChanges ? "checked" : ""}></label><label>Comment on selected block<textarea data-document-comment-draft maxlength="2000" placeholder="Add a private local comment"></textarea></label><button data-document-comment-add>Add comment</button>${changes || '<p class="document-review-empty">No pending tracked changes.</p>'}${comments || '<p class="document-review-empty">No comments yet.</p>'}</section>`;
  return `<div class="notes-format-bar office-doc-toolbar" role="toolbar" aria-label="Document formatting"><button data-document-format="bold"><strong>B</strong></button><button data-document-format="italic"><em>I</em></button><button data-document-format="code">Code</button><button data-document-format="highlight">Highlight</button><select data-document-add aria-label="Add block"><option value="">Add block…</option><option value="paragraph">Paragraph</option><option value="heading1">Heading 1</option><option value="heading2">Heading 2</option><option value="quote">Quote</option><option value="checklist">Checklist</option><option value="table">Table</option><option value="pagebreak">Page break</option></select><select data-document-align aria-label="Text alignment"><option value="left">Left</option><option value="center">Center</option><option value="right">Right</option><option value="justify">Justify</option></select><span></span><button class="${mode === "edit" ? "active" : ""}" data-note-mode="edit">Edit</button><button class="${mode === "preview" ? "active" : ""}" data-note-mode="preview">Reading view</button></div><div class="office-document-layout"><aside aria-label="Document settings"><h2>Page setup</h2><label>Size<select data-document-page="size"><option value="letter" ${document.page.size === "letter" ? "selected" : ""}>Letter</option><option value="a4" ${document.page.size === "a4" ? "selected" : ""}>A4</option></select></label><label>Orientation<select data-document-page="orientation"><option value="portrait" ${document.page.orientation === "portrait" ? "selected" : ""}>Portrait</option><option value="landscape" ${document.page.orientation === "landscape" ? "selected" : ""}>Landscape</option></select></label><label>Margins<input type="number" min="0.25" max="3" step="0.25" value="${document.page.margin}" data-document-page="margin"></label><label>Columns<select data-document-page="columns">${[1, 2, 3].map((columns) => `<option value="${columns}" ${document.page.columns === columns ? "selected" : ""}>${columns}</option>`).join("")}</select></label><label>Header<input maxlength="500" value="${escapeHtml(document.page.header)}" data-document-page="header"></label><label>Footer<input maxlength="500" value="${escapeHtml(document.page.footer)}" data-document-page="footer"></label>${review}</aside><div class="office-document-stage" data-page-size="${document.page.size}" data-page-orientation="${document.page.orientation}" style="--page-margin:${document.page.margin}in;--page-columns:${document.page.columns}">${mode === "edit" ? blockMarkup : `<article class="notes-preview office-page-preview"><header>${escapeHtml(document.page.header)}</header><div>${preview || "Start writing to see your document."}</div><footer>${escapeHtml(document.page.footer)}</footer></article>`}</div></div>`;
}

function creativeAssetEditor(project: OslCreativeProject): string {
  const selected = project.layers.find((layer) => layer.id === project.selectedLayerId) ?? project.layers[0] ?? null;
  const values = project.editor === "photo" && selected ? selected.adjustments : project.adjustments;
  const adjustment = (name: keyof OslCreativeProject["adjustments"], label: string, min: number, max: number, step = 1) => `<label><span>${label}</span><input type="range" min="${min}" max="${max}" step="${step}" value="${values[name]}" data-asset-adjustment="${name}"><output>${values[name]}</output></label>`;
  const layerRows = project.layers.map((layer, index) => `<div class="creative-layer-row ${layer.id === selected?.id ? "selected" : ""}"><button data-layer-visible="${layer.id}" aria-label="${layer.visible ? "Hide" : "Show"} ${escapeHtml(layer.name)}" aria-pressed="${layer.visible}">${layer.visible ? "◉" : "○"}</button><button data-layer-select="${layer.id}" aria-pressed="${layer.id === selected?.id}"><span>${escapeHtml(layer.name)}</span><small>${layer.type === "source" ? "Source" : "Adjustment"} · ${layer.opacity}%</small></button><button data-layer-move="up" data-layer-id="${layer.id}" aria-label="Move ${escapeHtml(layer.name)} up" ${index === project.layers.length - 1 ? "disabled" : ""}>↑</button><button data-layer-move="down" data-layer-id="${layer.id}" aria-label="Move ${escapeHtml(layer.name)} down" ${index === 0 ? "disabled" : ""}>↓</button></div>`).reverse().join("");
  const layerProperties = selected ? `<section class="creative-layer-properties"><label><span>Opacity</span><input type="range" min="0" max="100" value="${selected.opacity}" data-layer-opacity><output>${selected.opacity}</output></label><label><span>Blend mode</span><select data-layer-blend>${["normal", "multiply", "screen", "overlay", "darken", "lighten"].map((mode) => `<option value="${mode}" ${selected.blendMode === mode ? "selected" : ""}>${mode[0].toUpperCase()}${mode.slice(1)}</option>`).join("")}</select></label><label class="creative-check"><span>Layer mask</span><input type="checkbox" data-layer-mask ${selected.mask.enabled ? "checked" : ""}></label><label class="creative-check"><span>Invert mask</span><input type="checkbox" data-layer-mask-invert ${selected.mask.inverted ? "checked" : ""} ${selected.mask.enabled ? "" : "disabled"}></label><label><span>Mask feather</span><input type="range" min="0" max="100" value="${selected.mask.feather}" data-layer-mask-feather ${selected.mask.enabled ? "" : "disabled"}><output>${selected.mask.feather}</output></label></section>` : "";
  const photo = project.editor === "photo" ? `<section class="creative-layer-panel" aria-label="Photo layers"><div class="creative-layer-actions"><strong>Layers</strong><button data-layer-add title="Add adjustment layer">＋</button><button data-layer-duplicate title="Duplicate selected layer" ${selected ? "" : "disabled"}>⧉</button><button data-layer-delete title="Delete selected layer" ${selected?.type === "adjustment" ? "" : "disabled"}>×</button></div>${layerRows || "<p>No layers</p>"}</section>${layerProperties}<h2>Adjustments</h2>${adjustment("brightness", "Brightness", 0, 200)}${adjustment("contrast", "Contrast", 0, 200)}${adjustment("saturation", "Saturation", 0, 200)}${adjustment("blur", "Blur", 0, 20, .5)}${adjustment("rotate", "Rotate", -180, 180)}` : "";
  const playback = ["video", "audio"].includes(project.editor) ? adjustment("playbackRate", "Playback speed", .25, 4, .25) : "";
  let timeline = ""; if (project.workspace.kind === "timeline") { const workspace = project.workspace; const activeTrack = workspace.tracks.find((track) => track.id === workspace.selectedTrackId) ?? workspace.tracks[0]; const clip = activeTrack?.clips[0]; const trackRows = workspace.tracks.map((track) => `<div class="timeline-track ${track.id === activeTrack?.id ? "selected" : ""}"><button data-timeline-track="${track.id}"><span>${escapeHtml(track.name)}</span><small>${track.kind}</small></button><button data-timeline-mute="${track.id}" aria-label="${track.muted ? "Unmute" : "Mute"} ${escapeHtml(track.name)}" aria-pressed="${track.muted}">${track.muted ? "M" : "○"}</button><button data-timeline-lock="${track.id}" aria-label="${track.locked ? "Unlock" : "Lock"} ${escapeHtml(track.name)}" aria-pressed="${track.locked}">${track.locked ? "●" : "◇"}</button></div>`).join(""); timeline = `<section class="timeline-panel"><div class="timeline-actions"><strong>Timeline</strong><button data-timeline-add="${project.editor === "video" ? "video" : "audio"}">＋ Track</button><button data-timeline-add="motion">＋ Motion</button></div><label><span>Playhead</span><input type="range" min="0" max="${Math.max(1, workspace.duration)}" step=".01" value="${workspace.playhead}" data-timeline-playhead><output>${workspace.playhead.toFixed(2)}s</output></label>${trackRows}</section>${clip ? `<section class="timeline-clip-properties"><h2>${escapeHtml(clip.name)}</h2>${([ ["start", "Start", 0, 604800, .01], ["inPoint", "Source in", 0, 604800, .01], ["duration", "Duration", 0, 604800, .01], ["speed", "Speed", .25, 4, .05], ["volume", "Volume", 0, 200, 1], ["fadeIn", "Fade in", 0, 3600, .01], ["fadeOut", "Fade out", 0, 3600, .01] ] as const).map(([property, label, min, max, step]) => `<label><span>${label}</span><input type="number" min="${min}" max="${max}" step="${step}" value="${clip[property]}" data-timeline-clip="${property}" ${activeTrack.locked ? "disabled" : ""}></label>`).join("")}</section>` : ""}`; }
  let scene = ""; if (project.workspace.kind === "scene") { const workspace = project.workspace; const node = workspace.nodes.find((candidate) => candidate.id === workspace.selectedNodeId) ?? workspace.nodes[0]; scene = `<section class="scene-panel"><div class="timeline-actions"><strong>Scene</strong><button data-scene-add="camera">＋ Camera</button><button data-scene-add="light">＋ Light</button><button data-scene-add="empty">＋ Empty</button></div>${workspace.nodes.map((candidate) => `<div class="timeline-track ${candidate.id === node?.id ? "selected" : ""}"><button data-scene-node="${candidate.id}"><span>${escapeHtml(candidate.name)}</span><small>${candidate.type}</small></button><button data-scene-visible="${candidate.id}" aria-label="Toggle ${escapeHtml(candidate.name)} visibility">${candidate.visible ? "◉" : "○"}</button><button data-scene-lock="${candidate.id}" aria-label="Toggle ${escapeHtml(candidate.name)} lock">${candidate.locked ? "●" : "◇"}</button></div>`).join("")}</section>${node ? `<section class="scene-properties"><h2>${escapeHtml(node.name)}</h2><label><span>Material</span><input value="${escapeHtml(node.material)}" maxlength="80" data-scene-material></label>${(["position", "rotation", "scale"] as const).flatMap((vector) => ([0, 1, 2] as const).map((axis) => `<label><span>${vector} ${["X", "Y", "Z"][axis]}</span><input type="number" min="${vector === "scale" ? ".001" : "-1000000"}" max="1000000" step=".01" value="${node[vector][axis]}" data-scene-vector="${vector}" data-scene-axis="${axis}" ${node.locked ? "disabled" : ""}></label>`)).join("")}</section>` : ""}`; }
  const emptyState = project.editor === "asset" ? "<p>The encrypted original is preserved and can be exported without network conversion.</p>" : "";
  return `<div class="creative-asset-editor" data-creative-asset="${project.assetId}"><div class="creative-asset-toolbar"><span><strong>${escapeHtml(project.name)}</strong><small>${escapeHtml(project.mime)} · ${(project.size / 1024 / 1024).toFixed(1)} MiB · encrypted source</small></span><div>${project.editor === "photo" ? '<button data-asset-private-export>Export private PNG</button>' : ""}<button data-asset-download title="Preserves the imported file exactly, including original metadata">Export original</button></div></div><div class="creative-asset-workspace"><section class="creative-asset-preview"><div class="creative-asset-loading" role="status">Decrypting preview in memory…</div></section><aside><h2>${project.editor === "photo" ? "Photo adjustments" : project.editor === "video" ? "Video editor" : project.editor === "audio" ? "Audio editor" : project.editor === "model3d" ? "3D scene" : "Imported source"}</h2>${photo}${playback}${timeline}${scene}${emptyState}</aside></div></div>`;
}

function spreadsheetEditor(note: OslNote): string {
  const sheet = parseSheet(note.body) ?? parseSheet(defaultDocumentBody("spreadsheet"))!;
  const columns = Array.from({ length: sheet.columns }, (_, index) => sheetColumnLabel(index));
  let rowOrder = Array.from({ length: sheet.rows }, (_, row) => row); rowOrder = rowOrder.filter((row) => Object.entries(sheet.filters).every(([column, query]) => evaluateSheetCell(sheet, row, Number(column)).toLocaleLowerCase().includes(query.toLocaleLowerCase()))); if (sheet.sort) { const { column, direction } = sheet.sort; rowOrder.sort((left, right) => { const a = evaluateSheetCell(sheet, left, column); const b = evaluateSheetCell(sheet, right, column); const numeric = Number(a) - Number(b); const result = Number.isFinite(numeric) ? numeric : a.localeCompare(b, undefined, { numeric: true }); return direction === "ascending" ? result : -result; }); }
  const rows = rowOrder.map((row) => `<tr class="${row < sheet.frozenRows ? "frozen-row" : ""}"><th scope="row">${row + 1}</th>${columns.map((columnLabel, column) => { const raw = sheet.cells[`${row}:${column}`] ?? ""; const result = evaluateSheetCell(sheet, row, column); const format = sheet.formats[`${row}:${column}`] ?? "auto"; const invalid = sheetCellValidationMessage(sheet, row, column); const condition = sheetCellConditionColor(sheet, row, column); return `<td class="${raw.startsWith("=") ? "formula " : ""}format-${format} ${column < sheet.frozenColumns ? "frozen-column" : ""} ${invalid ? "invalid" : ""} ${condition ? `condition-${condition}` : ""}" style="--sheet-left:${46 + column * 128}px"><input class="sheet-cell" data-sheet-row="${row}" data-sheet-column="${column}" value="${escapeHtml(raw)}" aria-label="Cell ${columnLabel}${row + 1}, ${format}${raw.startsWith("=") ? `, result ${escapeHtml(result)}` : ""}${invalid ? `, invalid: ${escapeHtml(invalid)}` : ""}" ${invalid ? 'aria-invalid="true"' : ""} title="${invalid ? escapeHtml(invalid) : raw.startsWith("=") ? `${escapeHtml(raw)} → ${escapeHtml(result)}` : ""}">${raw.startsWith("=") ? `<output>${escapeHtml(result)}</output>` : ""}</td>`; }).join("")}</tr>`).join("");
  const columnOptions = columns.map((column, index) => `<option value="${index}" ${sheet.sort?.column === index ? "selected" : ""}>${column}</option>`).join("");
  const charts = sheet.charts.map((chart) => sheetChartMarkup(sheet, chart)).join("");
  const inspector = `<aside class="sheet-inspector" aria-label="Spreadsheet analysis"><section><h2>Selected cell</h2><label>Validation<select data-sheet-validation-kind><option value="">None</option><option value="number">Number range</option><option value="date">Date range</option><option value="list">Choice list</option></select></label><label>Rule<input data-sheet-validation-values maxlength="2000" placeholder="min, max or choice 1, choice 2"></label><button data-sheet-validation-apply>Apply validation</button><label>Conditional rule<select data-sheet-condition-operator><option value="">None</option><option value="greater">Greater than</option><option value="less">Less than</option><option value="contains">Text contains</option></select></label><label>Compare with<input data-sheet-condition-value maxlength="200"></label><label>Color<select data-sheet-condition-color><option value="cyan">Cyan</option><option value="green">Green</option><option value="amber">Amber</option><option value="red">Red</option></select></label><button data-sheet-condition-apply>Apply condition</button></section><section><h2>Charts</h2><label>Type<select data-sheet-chart-type><option value="bar">Bar</option><option value="line">Line</option><option value="pie">Pie</option></select></label><label>Title<input data-sheet-chart-title maxlength="120" placeholder="Chart title"></label><label>Labels<select data-sheet-chart-label>${columnOptions}</select></label><label>Values<select data-sheet-chart-value>${columnOptions}</select></label><button data-sheet-chart-add ${sheet.charts.length >= 20 ? "disabled" : ""}>Add local chart</button>${charts || '<p class="document-review-empty">No charts yet.</p>'}</section></aside>`;
  return `<div class="office-sheet-toolbar" role="toolbar"><button data-sheet-add-row>Add row</button><button data-sheet-add-column>Add column</button><button data-sheet-freeze="row" aria-pressed="${sheet.frozenRows > 0}">Freeze row</button><button data-sheet-freeze="column" aria-pressed="${sheet.frozenColumns > 0}">Freeze column</button><select data-sheet-sort-column aria-label="Sort column">${columnOptions}</select><button data-sheet-sort="ascending">Sort ↑</button><button data-sheet-sort="descending">Sort ↓</button><select data-sheet-format aria-label="Cell format"><option value="auto">Auto</option><option value="text">Text</option><option value="number">Number</option><option value="currency">Currency</option><option value="percent">Percent</option><option value="date">Date</option></select><button data-note-export="csv">Export CSV</button><span>${rowOrder.length}/${sheet.rows} rows · local formulas</span></div><div class="office-sheet-workspace"><div class="office-sheet-stage"><table><thead><tr><th></th>${columns.map((column) => `<th scope="col">${column}</th>`).join("")}</tr><tr class="sheet-filters"><th>Filter</th>${columns.map((column, index) => `<th><input value="${escapeHtml(sheet.filters[String(index)] ?? "")}" maxlength="200" data-sheet-filter="${index}" aria-label="Filter column ${column}"></th>`).join("")}</tr></thead><tbody>${rows}</tbody></table></div>${inspector}</div>`;
}

function drawingEditor(note: OslNote, attachments: OslAssetDescriptor[]): string {
  const drawing = parseDrawing(note.body) ?? parseDrawing(defaultDocumentBody("drawing"))!;
  const selected = drawing.items.find((item) => item.id === drawing.selectedId) ?? null;
  const selectedBoard = drawing.artboards.find((board) => board.id === drawing.selectedArtboardId) ?? drawing.artboards[0];
  const canvasWidth = Math.max(960, ...drawing.artboards.map((board) => board.x + board.width + 40));
  const canvasHeight = Math.max(540, ...drawing.artboards.map((board) => board.y + board.height + 40));
  const viewWidth = drawing.workspace.mode === "infinite" ? 960 / drawing.workspace.viewport.zoom : canvasWidth;
  const viewHeight = drawing.workspace.mode === "infinite" ? 540 / drawing.workspace.viewport.zoom : canvasHeight;
  const viewBox = drawing.workspace.mode === "infinite" ? `${drawing.workspace.viewport.x} ${drawing.workspace.viewport.y} ${viewWidth} ${viewHeight}` : `0 0 ${canvasWidth} ${canvasHeight}`;
  const gradients = drawing.items.filter((item) => item.gradientTo).map((item) => `<linearGradient id="gradient-${item.id}"><stop stop-color="${item.color}"/><stop offset="1" stop-color="${item.gradientTo}"/></linearGradient>`).join("");
  const artboardMarkup = drawing.artboards.map((board) => `<g data-drawing-artboard="${board.id}" class="drawing-artboard ${board.id === selectedBoard.id ? "selected" : ""}"><rect x="${board.x}" y="${board.y}" width="${board.width}" height="${board.height}" fill="${board.background}"/><text x="${board.x + 8}" y="${board.y + 22}">${escapeHtml(board.name)}</text></g>`).join("");
  const sourceMarkup = drawing.workspace.sources.map((source) => `<g data-drawing-source="${source.id}" opacity="${source.opacity / 100}"><rect x="${source.x}" y="${source.y}" width="${source.width}" height="${source.height}" class="drawing-source-frame"/><image data-drawing-source-image="${source.assetId}" x="${source.x}" y="${source.y}" width="${source.width}" height="${source.height}" preserveAspectRatio="xMidYMid meet"/><text x="${source.x + 14}" y="${source.y + 28}" class="drawing-source-label">${escapeHtml(source.name)}${source.mime === "application/pdf" ? ` · PDF page ${source.page}` : ""}</text></g>`).join("");
  const itemMarkup = drawing.items.filter((item) => !item.hidden).map((item) => { const attributes = `data-drawing-item="${item.id}" class="${drawing.selectedId === item.id ? "selected" : ""}" opacity="${item.opacity / 100}" transform="rotate(${item.rotation} ${item.x + item.width / 2} ${item.y + item.height / 2})"`; const fill = item.gradientTo ? `url(#gradient-${item.id})` : item.color; if (item.type === "rectangle") return `<rect ${attributes} x="${item.x}" y="${item.y}" width="${item.width}" height="${item.height}" rx="8" fill="${fill}" stroke="${item.stroke}" stroke-width="${item.strokeWidth}"/>`; if (item.type === "ellipse") return `<ellipse ${attributes} cx="${item.x + item.width / 2}" cy="${item.y + item.height / 2}" rx="${item.width / 2}" ry="${item.height / 2}" fill="${fill}" stroke="${item.stroke}" stroke-width="${item.strokeWidth}"/>`; if (item.type === "line" || item.type === "arrow") return `<line ${attributes} style="color:${item.stroke}" x1="${item.x}" y1="${item.y}" x2="${item.x + item.width}" y2="${item.y + item.height}" stroke-width="${item.strokeWidth}" stroke-linecap="round" ${item.type === "arrow" ? 'marker-end="url(#drawing-arrow)"' : ""}/>`; if (item.type === "path") return `<polyline ${attributes} points="${item.points.map((point) => `${point.x},${point.y}`).join(" ")}" fill="none" stroke="${item.stroke}" stroke-width="${item.strokeWidth}" stroke-linejoin="round" stroke-linecap="round"/>`; return `<text ${attributes} x="${item.x}" y="${item.y + 24}" fill="${fill}">${escapeHtml(item.text || "Text")}</text>`; }).join("");
  const colorOptions = (value: string) => [...drawingColors].map((color) => `<option value="${color}" ${value === color ? "selected" : ""}>${color}</option>`).join("");
  const link = selected ? drawing.prototype.links.find((candidate) => candidate.fromId === selected.id) : null;
  const constraint = selected ? drawing.constraints[selected.id] : null;
  const instanceComponent = selected ? drawing.components.find((component) => component.id === drawing.instances[selected.id]) : null;
  const boardOptions = drawing.artboards.map((board) => `<option value="${board.id}" ${constraint?.artboardId === board.id ? "selected" : ""}>${escapeHtml(board.name)}</option>`).join("");
  const properties = selected ? `<aside class="drawing-properties"><strong>${instanceComponent ? `Instance of ${escapeHtml(instanceComponent.name)}` : "Object"}</strong><label>Name<input value="${escapeHtml(selected.name)}" maxlength="80" data-drawing-property="name"></label>${(["x", "y", "width", "height"] as const).map((property) => `<label>${property}<input type="number" min="0" max="2000" value="${selected[property]}" data-drawing-property="${property}" ${selected.locked ? "disabled" : ""}></label>`).join("")}<label>Rotation<input type="number" min="-180" max="180" value="${selected.rotation}" data-drawing-property="rotation"></label><label>Opacity<input type="range" min="0" max="100" value="${selected.opacity}" data-drawing-property="opacity"></label>${selected.type === "text" ? `<label>Text<input value="${escapeHtml(selected.text)}" maxlength="500" data-drawing-property="text"></label>` : ""}<label>Fill<select data-drawing-property="color">${colorOptions(selected.color)}</select></label><label>Gradient<select data-drawing-property="gradientTo"><option value="">None</option>${colorOptions(selected.gradientTo ?? "")}</select></label><label>Stroke<select data-drawing-property="stroke">${colorOptions(selected.stroke)}</select></label><label>Stroke width<input type="range" min="0" max="64" value="${selected.strokeWidth}" data-drawing-property="strokeWidth"></label><label><span>Locked</span><input type="checkbox" data-drawing-property="locked" ${selected.locked ? "checked" : ""}></label><label><span>Hidden</span><input type="checkbox" data-drawing-property="hidden" ${selected.hidden ? "checked" : ""}></label><section class="drawing-constraints"><strong>Responsive constraints</strong><label>Artboard<select data-drawing-constraint="artboardId"><option value="">None</option>${boardOptions}</select></label><label>Horizontal<select data-drawing-constraint="horizontal" ${constraint ? "" : "disabled"}>${["left", "center", "right", "stretch"].map((value) => `<option value="${value}" ${constraint?.horizontal === value ? "selected" : ""}>${value}</option>`).join("")}</select></label><label>Vertical<select data-drawing-constraint="vertical" ${constraint ? "" : "disabled"}>${["top", "center", "bottom", "stretch"].map((value) => `<option value="${value}" ${constraint?.vertical === value ? "selected" : ""}>${value}</option>`).join("")}</select></label></section><section class="prototype-properties"><strong>Prototype</strong><button data-prototype-start aria-pressed="${drawing.prototype.startItemId === selected.id}">${drawing.prototype.startItemId === selected.id ? "Start frame" : "Set as start"}</button><label>Navigate to<select data-prototype-target><option value="">No interaction</option>${drawing.items.filter((item) => item.id !== selected.id).map((item) => `<option value="${item.id}" ${link?.toId === item.id ? "selected" : ""}>${escapeHtml(item.name)}</option>`).join("")}</select></label><label>Trigger<select data-prototype-trigger><option value="click" ${link?.trigger === "click" ? "selected" : ""}>Click</option><option value="hover" ${link?.trigger === "hover" ? "selected" : ""}>Hover</option><option value="keypress" ${link?.trigger === "keypress" ? "selected" : ""}>Key press</option></select></label><label>Transition<select data-prototype-transition><option value="instant" ${link?.transition === "instant" ? "selected" : ""}>Instant</option><option value="dissolve" ${link?.transition === "dissolve" ? "selected" : ""}>Dissolve</option><option value="slide" ${link?.transition === "slide" ? "selected" : ""}>Slide</option></select></label></section></aside>` : "";
  const artboardPanel = `<aside class="drawing-structure"><section><header><strong>Artboards</strong><button data-drawing-artboard-add ${drawing.artboards.length >= 32 ? "disabled" : ""}>Add</button></header>${drawing.artboards.map((board) => `<button class="${board.id === selectedBoard.id ? "active" : ""}" data-drawing-artboard-select="${board.id}">${escapeHtml(board.name)}<small>${board.width} × ${board.height}</small></button>`).join("")}<div class="drawing-artboard-properties"><label>Name<input data-artboard-property="name" maxlength="80" value="${escapeHtml(selectedBoard.name)}"></label>${(["x", "y", "width", "height"] as const).map((property) => `<label>${property}<input data-artboard-property="${property}" type="number" min="${property === "width" || property === "height" ? 1 : 0}" max="2000" value="${selectedBoard[property]}"></label>`).join("")}<label>Background<select data-artboard-property="background">${colorOptions(selectedBoard.background)}</select></label><button data-drawing-artboard-delete ${drawing.artboards.length === 1 ? "disabled" : ""}>Delete artboard</button></div></section><section><header><strong>Components</strong><button data-drawing-component-create ${!selected || drawing.components.length >= 128 || instanceComponent ? "disabled" : ""}>Create</button></header>${drawing.components.map((component) => `<article><span>${escapeHtml(component.name)}</span><button data-drawing-component-instance="${component.id}">New instance</button></article>`).join("") || "<p>No reusable components.</p>"}</section></aside>`;
  const sourceOptions = attachments.filter((asset) => asset.mime.startsWith("image/") || asset.mime === "application/pdf").filter((asset) => !drawing.workspace.sources.some((source) => source.assetId === asset.id)).map((asset) => `<option value="${asset.id}">${escapeHtml(asset.name)} · ${escapeHtml(asset.mime)}</option>`).join("");
  const annotationPanel = `<section><header><strong>Annotation sources</strong><span>${drawing.workspace.sources.length}/32</span></header>${drawing.workspace.sources.map((source) => `<article><span><strong>${escapeHtml(source.name)}</strong><small>${source.mime === "application/pdf" ? `PDF page ${source.page} · local decoder unavailable` : "Encrypted local image"}</small></span><button data-drawing-source-remove="${source.id}" aria-label="Remove ${escapeHtml(source.name)} from canvas">×</button></article>`).join("") || "<p>Attach an image or PDF to this file, then place it here.</p>"}<label>Attached file<select data-drawing-source-select aria-label="Attachment to annotate"><option value="">Choose…</option>${sourceOptions}</select></label><button data-drawing-source-add ${!sourceOptions || drawing.workspace.sources.length >= 32 ? "disabled" : ""}>Place on canvas</button><small>Images render locally from the encrypted vault. PDF pages stay as bounded placeholders until a verified local decoder is installed. OCR is unavailable; no text is guessed or uploaded.</small></section>`;
  return `<div class="office-drawing-toolbar" role="toolbar" aria-label="Canvas tools"><button data-drawing-mode="artboards" aria-pressed="${drawing.workspace.mode === "artboards"}">Artboards</button><button data-drawing-mode="infinite" aria-pressed="${drawing.workspace.mode === "infinite"}">Infinite canvas</button><button data-drawing-tool="select" aria-pressed="${drawing.workspace.tool === "select"}">Select</button><button data-drawing-tool="pen" aria-pressed="${drawing.workspace.tool === "pen"}">Ink</button><button data-drawing-tool="highlighter" aria-pressed="${drawing.workspace.tool === "highlighter"}">Highlighter</button><button data-drawing-tool="pan" aria-pressed="${drawing.workspace.tool === "pan"}">Pan</button><button data-drawing-zoom="out" aria-label="Zoom out">−</button><output aria-label="Canvas zoom">${Math.round(drawing.workspace.viewport.zoom * 100)}%</output><button data-drawing-zoom="in" aria-label="Zoom in">＋</button><button data-drawing-add="rectangle">Rectangle</button><button data-drawing-add="ellipse">Ellipse</button><button data-drawing-add="line">Line</button><button data-drawing-add="arrow">Arrow</button><button data-drawing-add="text">Text</button><span></span><button data-drawing-layer="back" ${selected ? "" : "disabled"}>Send back</button><button data-drawing-layer="front" ${selected ? "" : "disabled"}>Bring front</button><button data-drawing-duplicate ${selected ? "" : "disabled"}>Duplicate</button><button data-drawing-delete ${selected ? "" : "disabled"}>Delete</button></div><div class="office-drawing-stage">${drawing.workspace.mode === "artboards" ? artboardPanel : `<aside class="drawing-structure">${annotationPanel}</aside>`}<div class="drawing-canvas" data-drawing-tool-active="${drawing.workspace.tool}"><svg viewBox="${viewBox}" role="img" aria-label="${drawing.workspace.mode === "infinite" ? "Infinite encrypted drawing canvas" : `Drawing canvas with ${drawing.artboards.length} artboards`}" tabindex="0"><defs><pattern id="drawing-grid" width="24" height="24" patternUnits="userSpaceOnUse"><path d="M24 0H0V24" fill="none"/></pattern><marker id="drawing-arrow" markerWidth="10" markerHeight="10" refX="8" refY="3" orient="auto"><path d="M0 0 9 3 0 6Z" fill="context-stroke"/></marker>${gradients}</defs><rect x="${drawing.workspace.mode === "infinite" ? drawing.workspace.viewport.x : 0}" y="${drawing.workspace.mode === "infinite" ? drawing.workspace.viewport.y : 0}" width="${viewWidth}" height="${viewHeight}" fill="url(#drawing-grid)"/>${sourceMarkup}${drawing.workspace.mode === "artboards" ? artboardMarkup : ""}${itemMarkup}</svg></div>${properties}</div>`;
}

function presentationEditor(note: OslNote): string {
  const presentation = parsePresentation(note.body) ?? parsePresentation(defaultDocumentBody("presentation"))!; const active = presentation.slides.find((slide) => slide.id === presentation.selectedId)!;
  const thumbnails = presentation.slides.map((slide, index) => `<button class="slide-thumbnail ${slide.id === active.id ? "active" : ""}" data-slide-select="${slide.id}"><span>${index + 1}</span><div class="slide-mini theme-${slide.theme}"><strong>${escapeHtml(slide.title || "Untitled")}</strong><small>${escapeHtml(slide.body.slice(0, 80))}</small></div></button>`).join("");
  const animations = [...active.animations].sort((left, right) => left.order - right.order).map((animation) => `<article><span><strong>${animation.order}. ${animation.target}</strong><small>${animation.effect} · ${animation.delay}s delay · ${animation.duration}s</small></span><button data-slide-animation-delete="${animation.id}" aria-label="Delete ${animation.target} animation">×</button></article>`).join("");
  const presenterSlides = presentation.slides.map((slide, index) => { const animation = (target: "title" | "body") => [...slide.animations].sort((left, right) => left.order - right.order).find((item) => item.target === target); const titleAnimation = animation("title"); const bodyAnimation = animation("body"); const animated = (target: "title" | "body", content: string, item: SlideAnimation | undefined) => `<${target === "title" ? "h1" : "p"} data-presenter-${target} class="${item ? `presenter-animation effect-${item.effect}` : ""}" style="order:${slide.readingOrder.indexOf(target)};${item ? `--presenter-delay:${item.delay}s;--presenter-duration:${item.duration}s` : ""}">${escapeHtml(content)}</${target === "title" ? "h1" : "p"}>`; return `<section class="presenter-slide theme-${slide.theme} layout-${slide.layout}" data-presenter-slide="${index}" ${index === 0 ? "" : "hidden"}>${animated("title", slide.title, titleAnimation)}${animated("body", slide.body, bodyAnimation)}${presentation.master.footer ? `<small>${escapeHtml(presentation.master.footer)}${presentation.master.showNumbers ? ` · ${index + 1}` : ""}</small>` : ""}</section>`; }).join("");
  const presenterNotes = presentation.slides.map((slide, index) => `<div data-presenter-notes="${index}" ${index === 0 ? "" : "hidden"}><strong>Speaker notes</strong><p>${escapeHtml(slide.notes) || "No notes for this slide."}</p><small>${slide.duration}s planned</small></div>`).join("");
  const presenter = `<div class="slide-presenter" data-slide-presenter hidden role="dialog" aria-modal="true" aria-label="Local presenter view"><div class="presenter-audience">${presenterSlides}</div><aside><header><strong>Presenter view</strong><button data-slide-present-close aria-label="Close presenter view">×</button></header>${presenterNotes}<footer><button data-slide-present-previous disabled>Previous</button><output data-slide-present-count aria-live="polite">1 / ${presentation.slides.length}</output><button data-slide-present-next ${presentation.slides.length === 1 ? "disabled" : ""}>Next</button></footer></aside></div>`;
  return `<div class="office-slides"><aside><div><button data-slide-add>New</button><button data-slide-duplicate>Duplicate</button><button data-slide-delete ${presentation.slides.length === 1 ? "disabled" : ""}>Delete</button><button data-slide-present>Present</button></div>${thumbnails}<section class="slide-master"><strong>Master</strong><label>Footer<input id="slide-master-footer" maxlength="500" value="${escapeHtml(presentation.master.footer)}"></label><label><span>Slide numbers</span><input id="slide-master-numbers" type="checkbox" ${presentation.master.showNumbers ? "checked" : ""}></label></section></aside><section class="slide-stage"><div class="slide-canvas theme-${active.theme} layout-${active.layout}" data-transition="${active.transition}"><input id="slide-title" value="${escapeHtml(active.title)}" maxlength="200" placeholder="Presentation title" aria-label="Slide title"><textarea id="slide-body" maxlength="10000" placeholder="Add supporting text" aria-label="Slide body">${escapeHtml(active.body)}</textarea><div class="slide-options"><select id="slide-layout" aria-label="Slide layout">${["title", "content", "section", "blank"].map((layout) => `<option value="${layout}" ${active.layout === layout ? "selected" : ""}>${layout}</option>`).join("")}</select><select id="slide-theme" aria-label="Slide theme"><option value="cyan" ${active.theme === "cyan" ? "selected" : ""}>Cyan</option><option value="midnight" ${active.theme === "midnight" ? "selected" : ""}>Midnight</option><option value="paper" ${active.theme === "paper" ? "selected" : ""}>Paper</option><option value="sunset" ${active.theme === "sunset" ? "selected" : ""}>Sunset</option></select><select id="slide-transition" aria-label="Transition"><option value="none" ${active.transition === "none" ? "selected" : ""}>No transition</option><option value="fade" ${active.transition === "fade" ? "selected" : ""}>Fade</option><option value="slide" ${active.transition === "slide" ? "selected" : ""}>Slide</option></select><label>Seconds<input id="slide-duration" type="number" min=".5" max="3600" step=".5" value="${active.duration}"></label></div>${presentation.master.footer ? `<small class="slide-footer">${escapeHtml(presentation.master.footer)}${presentation.master.showNumbers ? ` · ${presentation.slides.indexOf(active) + 1}` : ""}</small>` : ""}</div><label class="speaker-notes">Speaker notes<textarea id="slide-notes" maxlength="20000" placeholder="Private presenter notes">${escapeHtml(active.notes)}</textarea></label><section class="slide-animation-panel" aria-label="Slide animations"><header><strong>Animations</strong><span>Local playback</span></header><div><select data-slide-animation-target aria-label="Animation target"><option value="title">Title</option><option value="body">Body</option></select><select data-slide-animation-effect aria-label="Animation effect"><option value="appear">Appear</option><option value="fade">Fade</option><option value="fly">Fly in</option></select><label>Delay<input data-slide-animation-delay type="number" min="0" max="300" step=".1" value="0"></label><label>Duration<input data-slide-animation-duration type="number" min=".1" max="30" step=".1" value=".6"></label><button data-slide-animation-add ${active.animations.length >= 20 ? "disabled" : ""}>Add</button></div>${animations || '<p class="document-review-empty">No element animations yet.</p>'}<label class="reading-order">Reading order<select data-slide-reading-order><option value="title-body" ${active.readingOrder[0] === "title" ? "selected" : ""}>Title, then body</option><option value="body-title" ${active.readingOrder[0] === "body" ? "selected" : ""}>Body, then title</option></select></label></section></section></div>${presenter}`;
}

export function officeEditorMarkup(note: OslNote, mode: NotesEditorMode, saveState: NotesSaveState, canUndo = false, canRedo = false, attachments: OslAssetDescriptor[] = []): string {
  const creative = parseOslCreativeProject(note.body);
  const content = creative ? creativeAssetEditor(creative) : note.kind === "document" ? documentEditor(note, mode) : note.kind === "spreadsheet" ? spreadsheetEditor(note) : note.kind === "drawing" ? drawingEditor(note, attachments) : note.kind === "presentation" ? presentationEditor(note) : '<div class="creative-asset-loading error">This creative project is malformed.</div>';
  return `<article class="notes-editor office-editor office-${note.kind}">${commonHeader(note, saveState, canUndo, canRedo)}${content}${officeAttachments(attachments)}${commonFooter(note)}</article>`;
}
